/**
 * Edit-then-charts parity (T429): one WinISD run where a single value was TYPED after the project was
 * loaded, then every chart, the Box/Vents readouts and the driver editor's values and E/C marks were
 * read. This loads the run's fixture (`winisd-edit-captures/<driver>/<box>-<field>.json`, generated by
 * winisd_research/toys/edit_fixture_json.py), loads the same base project into OpenISD, applies the same
 * edit through the object the UI writes (`writeSheetSlot`, as the What-if and Tune sheets do), and
 * compares.
 *
 * The WinISD side is parsed at the boundary into the typed `EditCapture`; nothing untyped goes past it.
 */
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {dirname, join} from 'node:path';
import {fileURLToPath} from 'node:url';
import {z} from 'zod';
import {createEngine} from '../../engine/Engine.js';
import type {BoxType} from '../../engine/index.js';
import type {LossChamber, VentPort} from '../../domain/box/box.js';
import type {FrequencyGrid} from '../../domain/box/frequencyGrid.js';
import type {NumericDriverSpecFieldName} from '../../domain/driver/driverSpecFieldName.js';
import type {OpenISDProject} from '../../domain/project/openISDProject.js';
import {readSheetSlot, ventOfSlot, writeSheetSlot} from '../../domain/project/sheetSlots.js';
import {WinIsdProjectConverter} from '../../domain/winIsdProjectConverter.js';
import type {SheetSlot} from '../../fields/sheetField.js';
import {reproduceWinisdBugs} from './domainBuilders.js';

const CAPTURES = join(dirname(fileURLToPath(import.meta.url)), 'winisd-edit-captures');

// ── the capture, parsed ──────────────────────────────────────────────────────────────────────────

/** The charts a run can hold, named as the WinISD run record names them. */
const QUANTITY = z.enum([
  'tfmag', 'spl', 'groupdelay', 'tfphase', 'excursion', 'impedance', 'maxpower', 'impedancephase', 'maxspl',
  'rearportvelocity', 'rearportgain', 'frontportvelocity', 'frontportgain', 'prtfmag', 'prexcursion',
]);
export type Quantity = z.infer<typeof QUANTITY>;

const MARK = z.enum(['E', 'C', 'N']);
export type Mark = z.infer<typeof MARK>;

const CHART = z.object({
  unit: z.string(),
  points: z.array(z.object({i: z.number().int(), f: z.number(), v: z.number()})),
});

const WIDGET = z.tuple([z.string(), z.tuple([z.number(), z.number(), z.number(), z.number()]), z.string(), z.boolean()]);
const INI = z.record(z.string(), z.record(z.string(), z.string()));

const CAPTURE = z.object({
  run: z.string(),
  grid: z.object({fmin: z.number(), fmax: z.number(), N: z.number().int(), step: z.number().int()}),
  edit: z.object({pane: z.string(), field: z.string(), typed: z.object({typed: z.string()}).nullable()}),
  editorAfter: z.record(z.string(), z.unknown()).nullable(),
  readoutsAfter: z.object({box_tab: z.array(WIDGET), vents_tab: z.array(WIDGET).optional()}),
  inputProject: INI,
  savedAfter: INI.nullable().optional(),
  charts: z.record(z.string(), CHART),
});

export interface ChartPoint { readonly i: number; readonly f: number; readonly v: number }

/** A run's WinISD side: the base project, the charts and readouts read after the run. */
export interface Capture {
  readonly run: string;
  readonly grid: FrequencyGrid & {readonly N: number};
  readonly pane: string;
  readonly field: string;
  readonly editor: ReadonlyMap<EditorField, EditorCell> | null;
  readonly boxTab: readonly Widget[];
  readonly ventsTab: readonly Widget[];
  /** The base `.wpr`, as WinISD wrote it before the edit. */
  readonly inputWpr: string;
  readonly inputProject: z.infer<typeof INI>;
  readonly charts: ReadonlyMap<Quantity, readonly ChartPoint[]>;
  /** The `.wpr` WinISD saved after the run, at full precision (the vent lengths it solved), when the run kept it. */
  readonly saved: z.infer<typeof INI> | null;
}

/** A run where a value was typed (`typed`), as opposed to a load-only run (`LoadCapture`). */
export interface EditCapture extends Capture { readonly typed: number }

/** A run where nothing was typed: the base project loaded, then read. */
export type LoadCapture = Capture;

export interface Widget { readonly cls: string; readonly x: number; readonly y: number; readonly text: string }
export interface EditorCell { readonly text: string; readonly mark: Mark }

/** The Parameters-tab fields of WinISD's driver editor, each with the OpenISD spec it shows. */
export interface EditorField {
  readonly key: string;
  readonly spec: NumericDriverSpecFieldName;
  /** WinISD prints the figure times this (the efficiency `no` as a percentage). */
  readonly printScale: number;
}
const field = (key: string, spec: NumericDriverSpecFieldName, printScale = 1): EditorField => ({key, spec, printScale});
export const EDITOR_FIELDS: readonly EditorField[] = [
  field('Qes', 'Qes'), field('Qms', 'Qms'), field('Qts', 'Qts'), field('Fs', 'Fs_hz'), field('Vas', 'Vas_m3'),
  field('Mms', 'Mms_kg'), field('Cms', 'Cms_m_per_N'), field('Rms', 'Rms_kg_per_s'), field('Re', 'Re_ohm'),
  field('BL', 'BL_Tm'), field('Dd', 'Dd_m'), field('Le', 'Le_H'), field('Sd', 'Sd_m2'), field('fLe', 'fLe_hz'),
  field('KLe', 'KLe_H_sqrtHz'), field('Xmax', 'Xmax_m'), field('Hc', 'Hc_m'), field('Hg', 'Hg_m'),
  field('Vd', 'Vd_m3'), field('Pe', 'Pe_W'), field('no', 'no', 100), field('Znom', 'Znom_ohm'),
  field('USPL', 'USPL_dB'), field('SPL', 'SPL_dB'), field('numVC', 'numVC'),
];

const EDITOR_CELL = z.tuple([z.string(), MARK]);

function iniText(ini: z.infer<typeof INI>): string {
  return Object.entries(ini).map(([section, keys]) =>
    `[${section}]\n${Object.entries(keys).map(([k, v]) => `${k}=${v}`).join('\n')}\n`).join('\n');
}

function widgets(raw: z.infer<typeof WIDGET>[] | undefined): readonly Widget[] {
  return (raw ?? []).map(([cls, [x, y], text]) => ({cls, x, y, text}));
}

/** Read and parse a run's fixture. Throws with the parser's message when the file is not a capture. */
export function loadEditCapture(driver: string, name: string): EditCapture {
  const raw = CAPTURE.parse(JSON.parse(readFileSync(join(CAPTURES, driver, `${name}.json`), 'utf8')));
  assert.ok(raw.edit.typed !== null, `${name}: nothing was typed in this run (use loadLoadCapture)`);
  const typed = Number(raw.edit.typed.typed);
  assert.ok(Number.isFinite(typed), `${name}: typed value ${raw.edit.typed.typed} is not a number`);
  return {...captureOf(raw), typed};
}

/** Read and parse a load-only run's fixture (no value was typed). */
export function loadLoadCapture(driver: string, name: string): LoadCapture {
  const raw = CAPTURE.parse(JSON.parse(readFileSync(join(CAPTURES, driver, `${name}.json`), 'utf8')));
  assert.ok(raw.edit.typed === null, `${name}: a value was typed in this run (use loadEditCapture)`);
  return captureOf(raw);
}

function captureOf(raw: z.infer<typeof CAPTURE>): Capture {
  const editorRaw = raw.editorAfter;
  const editor = editorRaw === null ? null : new Map(EDITOR_FIELDS.flatMap((f): [EditorField, EditorCell][] => {
    const cell = EDITOR_CELL.parse(editorRaw[f.key]);
    return [[f, {text: cell[0], mark: cell[1]}]];
  }));
  const charts = new Map(QUANTITY.options.flatMap((q): [Quantity, readonly ChartPoint[]][] => {
    const c = raw.charts[q];
    return c === undefined ? [] : [[q, c.points]];
  }));
  return {
    run: raw.run, grid: raw.grid, pane: raw.edit.pane, field: raw.edit.field, editor,
    boxTab: widgets(raw.readoutsAfter.box_tab), ventsTab: widgets(raw.readoutsAfter.vents_tab),
    inputWpr: iniText(raw.inputProject), inputProject: raw.inputProject, charts, saved: raw.savedAfter ?? null,
  };
}

// ── the edit, through the object the UI writes ───────────────────────────────────────────────────

/** One typed edit: the WinISD pane and field it was typed into, and the sheet slot OpenISD writes. */
export interface EditTarget {
  readonly pane: string;
  readonly field: string;
  readonly boxType: BoxType;
  readonly slot: SheetSlot;
}

export const DRIVER_VAS_EDIT: EditTarget = {pane: 'Driver', field: 'Vas', boxType: 'sealed', slot: 'driverVas'};
export const BOX_FB_EDIT: EditTarget = {pane: 'Box', field: 'Fb', boxType: 'vented', slot: 'ventTuning'};

/** A typed edit of a Driver-editor value: the spec field the editor writes (SI, as WinISD shows it). */
export interface SpecEditTarget { readonly pane: 'Driver'; readonly field: string; readonly spec: NumericDriverSpecFieldName }

/** The passive radiator's own spec fields a PR-pane edit types into. */
export type PrSpecFieldName = 'Fs_hz' | 'Qms' | 'Vas_m3' | 'Sd_m2' | 'Xmax_m';

/** The PR pane's own fields (not the radiator's spec): the added mass Me and the radiator count Npr. */
export type PrPaneFieldName = 'addedMass_kg' | 'count';

/** A typed edit in the PR pane: the field it writes (SI, as WinISD's file states it). */
export interface PrEditTarget { readonly pane: 'PR'; readonly field: string; readonly prSpec: PrSpecFieldName | PrPaneFieldName }

/** Which of a port's own fields a Vents-tab edit types into. */
export type VentEditKind = 'diameter' | 'endCorrection' | 'count';

/** A typed edit in the Vents tab of the box's rear (or only) port. */
export interface VentEditTarget {
  readonly pane: 'Vent';
  readonly field: string;
  readonly boxType: BoxType;
  readonly kind: VentEditKind;
}

/** A typed Loss-popup value: which of the box's loss sets (`lossGroupsOf` chamber) and which of its four Qs. */
export interface LossEditTarget {
  readonly pane: 'Loss';
  readonly field: string;
  readonly boxType: BoxType;
  readonly chamber: LossChamber;
  readonly kind: 'Ql' | 'Qa' | 'Qp' | 'Qicl';
}

/** A typed Vents-tab value of one named port of a multi-port box (the bandpass and ABC boxes). */
export interface PortEditTarget {
  readonly pane: 'VentFront' | 'VentRear' | 'VentIntra';
  readonly field: string;
  readonly boxType: BoxType;
  readonly port: VentPort['name'];
  readonly kind: VentEditKind | 'length';
}

/** A typed Signal-pane value: the amplifier's source resistance Rg, or the input power Pin. */
export interface SignalEditTarget { readonly pane: 'Signal'; readonly field: string; readonly signal: 'Pin' | 'Rg' }

/** Load the capture's base `.wpr` the way the app does, with every WinISD bug reproduced. */
export function loadBase(capture: Capture): OpenISDProject {
  const {value: project, errors} = new WinIsdProjectConverter(createEngine()).winIsdProjectToOpenIsdProject(capture.inputWpr);
  if (project === null) throw new Error('winIsdProjectToOpenIsdProject returned problems: ' + JSON.stringify(errors));
  reproduceWinisdBugs(project);
  project.rgAtDriverSide.set(false);
  return project;
}

function number(text: string | undefined, what: string): number {
  const n = Number(text);
  assert.ok(text !== undefined && Number.isFinite(n), `${what}: ${text} is not a number`);
  return n;
}

/** Load parity first: the project OpenISD loaded holds the base figures the file states. */
export function assertLoadParity(project: OpenISDProject, capture: Capture): void {
  const driver = capture.inputProject['Driver'];
  const box = capture.inputProject['Box'];
  assert.ok(driver !== undefined && box !== undefined, 'capture has no Driver/Box section');
  const same = (what: string, got: number | null, want: number): void => {
    assert.ok(got !== null && Math.abs(got - want) <= 1e-12 * Math.abs(want), `load: ${what} ${got} vs file ${want}`);
  };
  same('Fs', project.driver.specField('Fs_hz').value, number(driver['Fs'], 'Fs'));
  same('Qes', project.driver.specField('Qes').value, number(driver['Qes'], 'Qes'));
  same('Qms', project.driver.specField('Qms').value, number(driver['Qms'], 'Qms'));
  same('Vas', project.driver.specField('Vas_m3').value, number(driver['Vas'], 'Vas'));
  same('Re', project.driver.specField('Re_ohm').value, number(driver['Re'], 'Re'));
  same('BL', project.driver.specField('BL_Tm').value, number(driver['BL'], 'BL'));
  same('Sd', project.driver.specField('Sd_m2').value, number(driver['Sd'], 'Sd'));
  same('Vb', readSheetSlot(project, project.box.boxType.value, 'volume'), number(box['Vr'], 'Vr'));
}

/** Apply the capture's typed edit where the UI writes it. */
export function applyEdit(project: OpenISDProject, capture: EditCapture, target: EditTarget): void {
  assert.equal(capture.pane, target.pane, `${capture.run}: edit pane`);
  assert.equal(capture.field, target.field, `${capture.run}: edit field`);
  writeSheetSlot(project, target.boxType, target.slot, capture.typed);
}

/** Apply a typed Driver-editor value where the editor writes it. */
export function applySpecEdit(project: OpenISDProject, capture: EditCapture, target: SpecEditTarget): void {
  assert.equal(capture.pane, target.pane, `${capture.run}: edit pane`);
  assert.equal(capture.field, target.field, `${capture.run}: edit field`);
  project.driver.specField(target.spec).set(capture.typed);
}

/** Apply a typed PR-pane value where the radiator tab writes it. */
export function applyPrEdit(project: OpenISDProject, capture: EditCapture, target: PrEditTarget): void {
  assert.equal(capture.pane, target.pane, `${capture.run}: edit pane`);
  assert.equal(capture.field, target.field, `${capture.run}: edit field`);
  const pr = project.box.passiveRadiator;
  switch (target.prSpec) {
    case 'addedMass_kg': pr.addedMass_kg.set(capture.typed); break;
    case 'count': pr.count.set(capture.typed); break;
    case 'Fs_hz': case 'Qms': case 'Vas_m3': case 'Sd_m2': case 'Xmax_m': pr.radiator.spec[target.prSpec].set(capture.typed); break;
  }
}

/** Load parity of the PR pane: the radiator the project loaded holds the five figures the file states. */
export function assertPrLoadParity(project: OpenISDProject, capture: Capture): void {
  const pr = capture.inputProject['PassiveRadiator'];
  assert.ok(pr !== undefined, 'capture has no PassiveRadiator section');
  const spec = project.box.passiveRadiator.radiator.spec;
  const same = (what: string, got: number | null, want: number): void => {
    assert.ok(got !== null && Math.abs(got - want) <= 1e-12 * Math.abs(want), `load: PR ${what} ${got} vs file ${want}`);
  };
  same('Fs', spec.Fs_hz.value, number(pr['Fs'], 'PR Fs'));
  same('Qms', spec.Qms.value, number(pr['Qms'], 'PR Qms'));
  same('Vas', spec.Vas_m3.value, number(pr['Vas'], 'PR Vas'));
  same('Sd', spec.Sd_m2.value, number(pr['Sd'], 'PR Sd'));
  same('Xmax', spec.Xmax_m.value, number(pr['Xmax'], 'PR Xmax'));
}

/** Apply a typed Vents-tab value to the box's port, then let the port follow (length from the tuning). */
export function applyVentEdit(project: OpenISDProject, capture: EditCapture, target: VentEditTarget): void {
  assert.equal(capture.pane, target.pane, `${capture.run}: edit pane`);
  assert.equal(capture.field, target.field, `${capture.run}: edit field`);
  const vent = ventOfSlot(project, target.boxType, 'ventArea');
  assert.ok(vent !== null, `${capture.run}: the ${target.boxType} box has no port`);
  project.batch(() => {
    switch (target.kind) {
      case 'diameter': vent.diameter_m.set(capture.typed); break;
      case 'endCorrection': vent.endCorrection_m.set(capture.typed); break;
      case 'count': vent.count.set(capture.typed); break;
    }
    project.recalc();
  });
}

/** Apply a typed Loss-popup value where the popup writes it. */
export function applyLossEdit(project: OpenISDProject, capture: EditCapture, target: LossEditTarget): void {
  assert.equal(capture.pane, target.pane, `${capture.run}: edit pane`);
  assert.equal(capture.field, target.field, `${capture.run}: edit field`);
  const group = project.box.lossGroupsOf(target.boxType).find((g) => g.chamber === target.chamber);
  assert.ok(group !== undefined, `${capture.run}: the ${target.boxType} box has no ${target.chamber} loss set`);
  const field = target.kind === 'Ql' ? group.Ql : target.kind === 'Qa' ? group.Qa : target.kind === 'Qp' ? group.Qp : group.Qicl;
  assert.ok(field !== null, `${capture.run}: the ${target.chamber} loss set has no ${target.kind}`);
  field.set(capture.typed);
}

/** Apply a typed Vents-tab value to one named port, then let the port follow (length from the tuning). */
export function applyPortEdit(project: OpenISDProject, capture: EditCapture, target: PortEditTarget): void {
  assert.equal(capture.pane, target.pane, `${capture.run}: edit pane`);
  assert.equal(capture.field, target.field, `${capture.run}: edit field`);
  const port = project.box.ventPortsOf(target.boxType).find((p) => p.name === target.port);
  assert.ok(port !== undefined, `${capture.run}: the ${target.boxType} box has no ${target.port} port`);
  project.batch(() => {
    switch (target.kind) {
      case 'diameter': port.vent.diameter_m.set(capture.typed); break;
      case 'endCorrection': port.vent.endCorrection_m.set(capture.typed); break;
      case 'count': port.vent.count.set(capture.typed); break;
      case 'length': port.vent.length_m.set(capture.typed); break;
    }
    project.recalc();
  });
}

/** Apply a typed Signal-pane value where the amplifier panel writes it. */
export function applySignalEdit(project: OpenISDProject, capture: EditCapture, target: SignalEditTarget): void {
  assert.equal(capture.pane, target.pane, `${capture.run}: edit pane`);
  assert.equal(capture.field, target.field, `${capture.run}: edit field`);
  switch (target.signal) {
    case 'Pin': project.powerDrive_W.set(capture.typed); break;
    case 'Rg': project.Rs_ohm.set(capture.typed); break;
  }
}

// ── the charts ───────────────────────────────────────────────────────────────────────────────────

type Sweep = NonNullable<ReturnType<OpenISDProject['sweep']>['values']>;
type MaxCurves = NonNullable<ReturnType<OpenISDProject['maxCurves']>['values']>;

export interface Swept { readonly sw: Sweep; readonly mx: MaxCurves }

export function sweepAfterEdit(project: OpenISDProject, capture: Capture): Swept {
  const grid: FrequencyGrid = {fmin: capture.grid.fmin, fmax: capture.grid.fmax, N: capture.grid.N};
  const sw = project.sweep(grid);
  const mx = project.maxCurves(grid);
  if (sw.values === null || mx.values === null) throw new Error('sweep refused: ' + JSON.stringify([sw.issues, mx.issues]));
  return {sw: sw.values, mx: mx.values};
}

/** How a chart is compared: OpenISD's series, in WinISD's plotted unit, and the allowed difference. */
interface ChartRule {
  readonly series: (s: Swept) => readonly number[] | null;
  /** Largest allowed |OpenISD - WinISD| at WinISD value `v`. */
  readonly bound: (v: number) => number;
  /** Phase charts: the difference is taken modulo a full turn. */
  readonly turn?: number;
}

const abs = (tol: number) => (): number => tol;
const rel = (tol: number) => (v: number): number => tol * Math.abs(v);
const deg = (rad: readonly number[]): readonly number[] => rad.map((r) => r * 180 / Math.PI);

/** Group delay is matched to WinISD's own 1e-10 Hz finite-difference noise (register: sealed 6.9e-4,
 *  vented 1.0e-3 ms); bp6/abc ≤ 0.15 ms. */
export const GROUP_DELAY_BOUND_MS = 2e-3;

export function chartRules(groupDelayBound_ms: number): Readonly<Record<Quantity, ChartRule>> {
  return {
    tfmag: {series: ({sw}) => sw.tfMag, bound: abs(1e-9)},
    spl: {series: ({sw}) => sw.spl, bound: abs(1e-9)},
    groupdelay: {series: ({sw}) => sw.gd, bound: abs(groupDelayBound_ms)},
    tfphase: {series: ({sw}) => deg(sw.phase), bound: abs(1e-9), turn: 360},
    excursion: {series: ({sw}) => sw.exc, bound: rel(1e-9)},
    impedance: {series: ({sw}) => sw.zmag, bound: rel(1e-9)},
    maxpower: {series: ({mx}) => mx.maxpwr, bound: rel(1e-9)},
    impedancephase: {series: ({sw}) => sw.zph, bound: abs(1e-9), turn: 360},
    maxspl: {series: ({mx}) => mx.maxspl, bound: abs(1e-9)},
    // A bandpass6 keeps its rear port's velocity apart (`pvRear`); every other box has one port, in `pv`.
    rearportvelocity: {series: ({sw}) => sw.pvRear ?? sw.pv, bound: rel(1e-9)},
    rearportgain: {series: ({sw}) => sw.rearPortGain, bound: abs(1e-9)},
    frontportvelocity: {series: ({sw}) => sw.pv, bound: rel(1e-9)},
    frontportgain: {series: ({sw}) => sw.frontPortGain, bound: abs(1e-9)},
    prtfmag: {series: ({sw}) => sw.prTfMag, bound: abs(1e-9)},
    prexcursion: {series: ({sw}) => sw.excPR, bound: rel(1e-9)},
  };
}

/** The worst |OpenISD - WinISD| over the captured points of one chart, or throws if OpenISD has no such curve. */
export function worstDeviation(capture: Capture, swept: Swept, quantity: Quantity, rule: ChartRule): {worst: number; excess: number; at: number} {
  const points = capture.charts.get(quantity);
  assert.ok(points !== undefined, `${capture.run}: no ${quantity} chart captured`);
  const got = rule.series(swept);
  assert.ok(got !== null, `${quantity}: OpenISD has no such curve`);
  let worst = 0;
  let excess = -Infinity;
  let at = NaN;
  for (const p of points) {
    const v = got[p.i];
    assert.ok(v !== undefined, `${quantity}: no OpenISD point ${p.i}`);
    let d = Math.abs(v - p.v);
    if (rule.turn !== undefined) d = Math.min(d % rule.turn, rule.turn - (d % rule.turn));
    worst = Math.max(worst, d);
    if (d - rule.bound(p.v) > excess) { excess = d - rule.bound(p.v); at = p.f; }
  }
  return {worst, excess, at};
}

/** Every captured point of `quantity` sits within the chart's bound. */
export function assertChartMatches(capture: Capture, swept: Swept, quantity: Quantity, rules: Readonly<Record<Quantity, ChartRule>>): void {
  const {worst, excess, at} = worstDeviation(capture, swept, quantity, rules[quantity]);
  assert.ok(excess <= 0, `${quantity} after ${capture.pane}.${capture.field}: worst ${worst} at ${at} Hz is ${excess} over the bound`);
}

// ── readouts (WinISD prints them to a fixed number of places) ────────────────────────────────────

/** The editor fields a file need not state: WinISD shows them as entered zeros. */
export const UNSTATED_ZERO_KEYS: readonly string[] = ['fLe', 'KLe', 'Hc', 'Hg'];

/** Where WinISD's tabs print a readout: the control's class and top-left corner in the pane. */
export interface ReadoutSpot { readonly tab: 'box' | 'vents'; readonly cls: string; readonly x: number; readonly y: number }

export const SEALED_QTC: ReadoutSpot = {tab: 'box', cls: 'Window', x: 107, y: 662};
export const SEALED_FSC: ReadoutSpot = {tab: 'box', cls: 'Edit', x: 107, y: 624};
export const BOX_VOLUME: ReadoutSpot = {tab: 'box', cls: 'Edit', x: 107, y: 584};
export const VENTED_FB: ReadoutSpot = {tab: 'box', cls: 'Edit', x: 107, y: 624};
export const VENT_LENGTH: ReadoutSpot = {tab: 'vents', cls: 'Edit', x: 111, y: 638};
export const VENT_CROSS_AREA: ReadoutSpot = {tab: 'vents', cls: 'Edit', x: 111, y: 676};
/** Two-chamber boxes: the front chamber's readouts sit to the right of the rear chamber's. */
export const FRONT_BOX_VOLUME: ReadoutSpot = {tab: 'box', cls: 'Edit', x: 262, y: 584};
export const FRONT_TUNING: ReadoutSpot = {tab: 'box', cls: 'Edit', x: 262, y: 624};
export const FRONT_VENT_LENGTH: ReadoutSpot = {tab: 'vents', cls: 'Edit', x: 312, y: 638};
export const FRONT_VENT_CROSS_AREA: ReadoutSpot = {tab: 'vents', cls: 'Edit', x: 312, y: 674};
/** The ABC box's intrachamber port prints to the right of the front port's. */
export const INTRA_VENT_LENGTH: ReadoutSpot = {tab: 'vents', cls: 'Edit', x: 514, y: 638};
export const INTRA_VENT_CROSS_AREA: ReadoutSpot = {tab: 'vents', cls: 'Edit', x: 514, y: 674};
/** The passive radiator box prints its tuning where the sealed box prints Fsc. */
export const PR_TUNING: ReadoutSpot = {tab: 'box', cls: 'Edit', x: 107, y: 624};

/** What WinISD printed at `spot`, as text, with the number of decimals it printed. */
export function printed(capture: Capture, spot: ReadoutSpot): {value: number; decimals: number} {
  const list = spot.tab === 'box' ? capture.boxTab : capture.ventsTab;
  const w = list.find((c) => c.cls === spot.cls && c.x === spot.x && c.y === spot.y);
  assert.ok(w !== undefined, `${capture.run}: no ${spot.cls} at ${spot.x},${spot.y} on the ${spot.tab} tab`);
  return {value: number(w.text, `readout ${spot.x},${spot.y}`), decimals: (w.text.split('.')[1] ?? '').length};
}

/** OpenISD's value, rounded to the places WinISD printed, equals the print. */
export function assertReadout(capture: Capture, spot: ReadoutSpot, got: number | null, what: string): void {
  const {value, decimals} = printed(capture, spot);
  assert.ok(got !== null, `${what}: OpenISD has no value`);
  assert.ok(Math.abs(got - value) <= 0.5 * 10 ** -decimals * (1 + 1e-9), `${what}: OpenISD ${got}, WinISD printed ${value} (${decimals} dp)`);
}

// ── the driver editor: value and E/C mark of every field ─────────────────────────────────────────

/** WinISD marks the voice-coil count with neither E nor C (black, 'N'), whether the file states it or not. */
const NEVER_MARKED: readonly NumericDriverSpecFieldName[] = ['numVC'];

export function openIsdMark(project: OpenISDProject, spec: NumericDriverSpecFieldName): Mark {
  const f = project.driver.specField(spec);
  if (NEVER_MARKED.includes(spec)) return 'N';
  if (f.entered) return 'E';
  if (f.calculated) return 'C';
  return 'N';
}

/** The fields the file leaves out (fLe, KLe, Hc, Hg) stay blank in OpenISD: mark N, no value (John, QO279). */
export function unstatedBlankDeviations(project: OpenISDProject, capture: Capture): readonly string[] {
  const out: string[] = [];
  if (capture.editor === null) return out;
  for (const [f] of capture.editor) {
    if (!UNSTATED_ZERO_KEYS.includes(f.key)) continue;
    const mark = openIsdMark(project, f.spec);
    const raw = project.driver.specField(f.spec).value;
    if (mark !== 'N' || raw !== null) out.push(`${f.key}: mark ${mark}, value ${raw}`);
  }
  return out;
}

/** Every editor field: OpenISD's mark equals WinISD's, and its value rounds to what WinISD printed. */
export function editorDeviations(project: OpenISDProject, capture: Capture, only: (f: EditorField) => boolean): readonly string[] {
  const out: string[] = [];
  if (capture.editor === null) return out;
  for (const [f, cell] of capture.editor) {
    if (!only(f)) continue;
    const mark = openIsdMark(project, f.spec);
    if (mark !== cell.mark) out.push(`${f.key}: mark ${mark}, WinISD ${cell.mark}`);
    const want = number(cell.text, f.key);
    const decimals = (cell.text.split('.')[1] ?? '').length;
    const raw = project.driver.specField(f.spec).value;
    const got = raw === null ? null : raw * f.printScale;
    if (got === null || Math.abs(got - want) > 0.5 * 10 ** -decimals * (1 + 1e-9)) out.push(`${f.key}: value ${got}, WinISD printed ${cell.text}`);
  }
  return out;
}
